
(()=>{
'use strict';
const root=document.getElementById('milky-way-ascii'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d',{alpha:false});
const get=id=>root.querySelector('#space-'+id);
const angle=get('angle'),colour=get('colour'),vividness=get('vividness'),starsToggle=get('stars'),galaxiesToggle=get('galaxies'),play=get('play'),style=get('style'),detail=get('detail'),status=get('status');
const source=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const ramp=' .,:;irsXA253hMHGS#9B&@';
const W=640;let H=400,fps=20;
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,visible=true,time=0,last=0,drawn=0,frames=0;
let cols=0,rows=0,starMap=[],galaxyMap=[],galaxyIndex=[];
function resizeScene(){H=W*innerHeight/innerWidth;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(innerWidth*dpr);canvas.height=Math.round(innerHeight*dpr);cols=0;}
resizeScene();
let seed=73021;
function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}
const stars=Array.from({length:165},()=>({x:12+random()*(W-24),y:12+random()*376,phase:random()*Math.PI*2,rate:.45+random()*.7,power:.3+random()*.7,large:random()>.86,tint:random()}));
const galaxies=[{x:86,y:74,sx:45,sy:21,angle:-.45,tint:0},{x:554,y:321,sx:45,sy:24,angle:.65,tint:1},{x:96,y:337,sx:26,sy:13,angle:.3,tint:2}];
function cache(){
 const n=+detail.value;if(n===cols)return;cols=n;rows=Math.round(cols*H/W/1.44);
 starMap=new Int16Array(cols*rows).fill(-1);galaxyMap=new Float32Array(cols*rows);galaxyIndex=new Int8Array(cols*rows).fill(-1);
 stars.forEach((s,i)=>{const x=Math.floor(s.x/W*cols),y=Math.min(rows-1,Math.floor(s.y/400*rows));starMap[y*cols+x]=i;});
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){
  const x=(col+.5)/cols*W,y=(row+.5)/rows*H,i=row*cols+col;
  galaxies.forEach((g,k)=>{
   const dx=x-g.x,dy=y-g.y/400*H,ca=Math.cos(g.angle),sa=Math.sin(g.angle);
   const gx=(dx*ca+dy*sa)/g.sx,gy=(-dx*sa+dy*ca)/g.sy,r=Math.hypot(gx,gy);
   if(r>1.45)return;
   const theta=Math.atan2(gy,gx),arm=Math.pow((Math.cos(2*(theta-3.8*Math.log(r+.15)))+1)*.5,6);
   const grain=.8+.2*Math.sin(col*4.12+row*7.73+k);
   const value=(.88*Math.exp(-r*6.8)+.48*arm*Math.exp(-r*1.95)+.045*Math.exp(-r*3))*grain;
   if(value>galaxyMap[i]){galaxyMap[i]=value;galaxyIndex[i]=k;}
  });
 }
}
function restore(state=window.openai?.widgetState){
 const s=state?.modelContent;
 if(s){
  if(['tiles','ascii'].includes(s.rendering))style.value=s.rendering;
  if([128,176,240].includes(s.detail))detail.value=String(s.detail);
  if(Number.isFinite(s.vividness))vividness.value=String(clamp(s.vividness,0,100));
  if(Number.isFinite(s.angle))angle.value=String(clamp(s.angle,-180,180));
  if(typeof s.background==='string'&&/^#[0-9a-f]{6}$/i.test(s.background))colour.value=s.background;
  if(typeof s.stars==='boolean')starsToggle.checked=s.stars;
  if(typeof s.galaxies==='boolean')galaxiesToggle.checked=s.galaxies;
 }
 if(typeof state?.privateContent?.paused==='boolean')paused=state.privateContent.paused;
 play.textContent=paused?'Play':'Pause';labels();draw();
}
function labels(){get('vividness-value').textContent=vividness.value+'%';get('angle-value').textContent=angle.value+'°';get('colour-value').textContent=colour.value.toUpperCase();}
function save(){window.openai?.setWidgetState?.({modelContent:{scene:'Milky Way preview',vividness:+vividness.value,angle:+angle.value,background:colour.value,stars:starsToggle.checked,galaxies:galaxiesToggle.checked,rendering:style.value,detail:+detail.value},privateContent:{paused}})?.catch(()=>{});}
function mix(bg,target,a){return `rgb(${Math.round(bg[0]+(target[0]-bg[0])*a)},${Math.round(bg[1]+(target[1]-bg[1])*a)},${Math.round(bg[2]+(target[2]-bg[2])*a)})`;}
function smooth(a,b,x){const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);}
function grain(x,y){const z=Math.sin(x*127.1+y*311.7)*43758.5453;return z-Math.floor(z);}
function sample(x,y,k){
 x=clamp(x,0,639);y=clamp(y,0,164);
 const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;
 const jx=Math.min(639,ix+1),jy=Math.min(164,iy+1);
 return source[(iy*640+ix)*3+k]*(1-fx)*(1-fy)+source[(iy*640+jx)*3+k]*fx*(1-fy)+source[(jy*640+ix)*3+k]*(1-fx)*fy+source[(jy*640+jx)*3+k]*fx*fy;
}
function draw(){
 cache();const vivid=clamp(+vividness.value/100,0,1);const cw=canvas.width/cols,ch=canvas.height/rows,tiles=style.value==='tiles';
 const bg=[1,3,5].map(i=>parseInt(colour.value.slice(i,i+2),16));
 const light=window.SceneSettings.isLight(colour.value);
 ctx.fillStyle=colour.value;ctx.fillRect(0,0,canvas.width,canvas.height);
 ctx.font=`500 ${ch*.86}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';
 const rotation=+angle.value*Math.PI/180,ca=Math.cos(rotation),sa=Math.sin(rotation);
 // Crop through a longer galactic ribbon: its ends remain outside every rotated viewport.
 const lengthScale=(Math.abs(ca)*W+Math.abs(sa)*H+160)/560;
 const widthScale=1.35;
 const paleStar=light?[35,42,62]:[216,229,255],warmStar=light?[74,45,28]:[255,222,175];
 const mutedTints=light?[[60,48,93],[86,48,64],[33,63,79]]:[[185,177,255],[246,185,216],[162,218,244]];
 const richTints=light?[[111,33,151],[161,35,91],[0,101,143]]:[[194,95,255],[255,103,183],[66,225,255]];
 const galaxyTints=mutedTints.map((t,k)=>t.map((c,j)=>c+(richTints[k][j]-c)*vivid));
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){
  const i=row*cols+col,px=col*cw,py=row*ch,vx=(col+.5)/cols*W-W/2,vy=(row+.5)/rows*H-H/2;
  if(galaxiesToggle.checked&&galaxyIndex[i]>=0){
   const k=galaxyIndex[i],shine=.82+.11*Math.sin(time*.43+k*2)+.07*Math.sin(time*.83+k),v=galaxyMap[i]*shine*(1+.4*vivid);
   if(v>.023){
    if(tiles){ctx.fillStyle=mix(bg,galaxyTints[k],Math.min(.3+.24*vivid,v*(.45+.35*vivid)));ctx.fillRect(px,py,cw-.65,ch-.65);}
    ctx.fillStyle=mix(bg,galaxyTints[k],Math.min(1,.12+.04*vivid+v*(1.55+.5*vivid)));
    ctx.fillText(' .,:;*oO@'[clamp(Math.floor(v*12),1,8)],px+cw*.5,py+ch*.5,cw*.96);
   }
  }
  // The photo's star clouds move together. Smooth sampling keeps the dust lanes intact.
  const x=(ca*vx+sa*vy)/lengthScale+320,y=(-sa*vx+ca*vy)/widthScale+82.5;
  {
   const sx=x+2.8*Math.sin(time*.15)+.3*Math.sin(y*.07-time*.24);
   // Gently compress the source's outer rows instead of exposing the photograph's boundary.
   const sy=82+68*Math.tanh((y-82)/68)+.7*Math.sin(x*.018-time*.19);
   const r=sample(sx,sy,0),g=sample(sx,sy,1),b=sample(sx,sy,2),lum=(r*.2126+g*.7152+b*.0722)/255;
   const centre=84+6*Math.sin(x*.012)+4*Math.sin(x*.029);
   const spread=48+4*Math.sin(x*.021+1);
   const edge=Math.exp(-.5*Math.pow(Math.abs(y-centre)/spread,3));
   const pulse=.96+.035*Math.sin(x*.043-time*.55)+.025*Math.sin(y*.08+x*.012+time*.41);
   const density=Math.pow(clamp((lum-.065)/.51,0,1),1.15)*edge*pulse;
   const noise=grain(col,row),pepper=.92+.08*noise;
   if(density>.002){
    // Boost chromatic structure from the reference: cyan shadows, violet clouds, rose-gold cores.
    const warmth=clamp(.48+(r-b)/62,0,1);
    const cool=light?[0,84,149]:[63,183,255],violet=light?[100,33,157]:[182,108,255],warm=light?[164,36,88]:[255,116,162];
    const blend=warmth<.5?warmth*2:(warmth-.5)*2;
    const from=warmth<.5?cool:violet,to=warmth<.5?violet:warm;
    const core=smooth(.48,.94,density/Math.max(.001,edge))*(light?.12:.43);
    const coreTint=light?[126,63,31]:[255,230,190];
    const rich=from.map((v,k)=>{const colour=v+(to[k]-v)*blend;return colour+(coreTint[k]-colour)*core;});
    const muted=light?[48+r*.14,40+g*.10,49+b*.10]:[Math.min(255,r*1.12+94),Math.min(255,g*1.12+94),Math.min(255,b*1.12+94)];
    const target=muted.map((v,k)=>v+(rich[k]-v)*vivid);
    const intensity=clamp(density*pepper,0,1);
    if(tiles){ctx.fillStyle=mix(bg,target,intensity*(.61+.17*vivid)*smooth(0,.1,density));ctx.fillRect(px,py,cw-.65,ch-.65);}
    ctx.fillStyle=mix(bg,target,smooth(0,.055,density)*Math.min(1,intensity*(1.2+.22*vivid)+(.035+.01*vivid)*edge));
    const glyph=' .,:;irsXA253hMHGS#9B&@'[clamp(Math.floor(intensity*21),1,21)];
    ctx.fillText(glyph,px+cw*.5,py+ch*.5,cw*.96);
   }
  }
  // Independently twinkling foreground stars remain crisp above the galactic band.
  if(starsToggle.checked&&starMap[i]>=0){
   const s=stars[starMap[i]],shine=s.power*(.35+.65*(.5+.5*Math.sin(time*s.rate+s.phase)));
   ctx.fillStyle=mix(bg,s.tint>.72?warmStar:paleStar,.18+shine*.8);
   ctx.fillText(s.large?(shine>.64?'*':'+'):(shine>.65?':':'.'),px+cw*.5,py+ch*.5,cw*.96);
  }
 }
 canvas.dataset.frames=String(++frames);canvas.dataset.time=time.toFixed(3);
}
let raf=0;function schedule(){if(!raf&&!paused&&visible&&!document.hidden)raf=requestAnimationFrame(tick);}
function tick(now){raf=0;if(!last)last=now;const dt=Math.min(.06,(now-last)/1000);last=now;if(!paused&&visible&&!document.hidden){time+=dt;if(now-drawn>=1000/fps-.5){drawn=now;draw();}}schedule();}
play.addEventListener('click',()=>{paused=!paused;play.textContent=paused?'Play':'Pause';status.textContent=paused?'Animation paused':'Animation playing';save();});
for(const el of [angle,colour,vividness]){el.addEventListener('input',()=>{labels();draw();});el.addEventListener('change',save);}
for(const el of [style,detail,starsToggle,galaxiesToggle])el.addEventListener('change',()=>{draw();save();});
new IntersectionObserver(e=>{visible=e[0].isIntersecting;last=0;schedule();}).observe(canvas);
window.ASCIIWallpaper={
 configure(s){s=window.SceneSettings.normalize(s);fps=s.fps;colour.value=s.background;angle.value=String(s.angle);vividness.value=String(s.vividness??70);starsToggle.checked=!!s.stars;galaxiesToggle.checked=!!s.galaxies;style.value=s.style;detail.value=String(s.detail);paused=!!s.paused;last=0;labels();draw();schedule();},
 launch(){},state(){return {...canvas.dataset,scene:'milky-way',paused,fps,light:window.SceneSettings.isLight(colour.value),background:colour.value,angle:+angle.value,vividness:+vividness.value,width:canvas.width,height:canvas.height};}
};
window.addEventListener('resize',()=>{resizeScene();draw();});document.addEventListener('visibilitychange',()=>{last=0;schedule();});
restore();schedule();
})();
